// Tokenizer for the Nix language, producing (kind, start, end) byte ranges.
use crate::syntax::SyntaxKind::{self, *};

fn is_valid_path_char(c: char) -> bool {
    matches!(c, 'a'..='z' | 'A'..='Z' | '0'..='9' | '/' | '_' | '.' | '+' | '-')
}

fn is_valid_uri_char(c: char) -> bool {
    match c {
        '%' | '?' | ':' | '@' | '&' | '=' | '$' | ',' | '!' | '~' | '*' | '\'' | '/' | '.' | '_'
        | '-' | '+' => true,
        c => c.is_ascii_alphanumeric(),
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum IdentType {
    Ident,
    Path,
    Store,
    Uri,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Context {
    StringBody { multiline: bool },
    StringEnd,
    Interpol { brackets: u32 },
    InterpolStart,
    Path,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Token {
    pub kind: SyntaxKind,
    pub start: usize,
    pub end: usize,
}

pub struct Tokenizer<'a> {
    ctx: Vec<Context>,
    input: &'a str,
    offset: usize,
}

impl<'a> Tokenizer<'a> {
    pub fn new(input: &'a str) -> Self {
        Tokenizer { ctx: Vec::new(), input, offset: 0 }
    }

    fn remaining(&self) -> &'a str {
        &self.input[self.offset..]
    }

    fn peek(&self) -> Option<char> {
        self.remaining().chars().next()
    }

    fn next_char(&mut self) -> Option<char> {
        let c = self.peek();
        if let Some(c) = c {
            self.offset += c.len_utf8();
        }
        c
    }

    fn starts_with_bump(&mut self, s: &str) -> bool {
        let starts_with = self.remaining().starts_with(s);
        if starts_with {
            self.offset += s.len();
        }
        starts_with
    }

    fn str_since(&self, past: usize) -> &'a str {
        &self.input[past..self.offset]
    }

    fn push_ctx(&mut self, ctx: Context) {
        self.ctx.push(ctx)
    }

    fn pop_ctx(&mut self) {
        self.ctx.pop();
    }

    fn consume<F: FnMut(char) -> bool>(&mut self, mut f: F) -> usize {
        let len: usize =
            self.remaining().chars().take_while(|&c| f(c)).map(|c| c.len_utf8()).sum::<usize>();
        self.offset += len;
        len
    }

    fn next_string(&mut self, multiline: bool) -> SyntaxKind {
        loop {
            let start = self.offset;
            match self.next_char() {
                None => {
                    self.pop_ctx();
                    return TOKEN_ERROR;
                }
                Some('"') if !multiline => {
                    self.offset = start;
                    self.pop_ctx();
                    self.push_ctx(Context::StringEnd);
                    return TOKEN_STRING_CONTENT;
                }
                Some('\\') if !multiline => match self.next_char() {
                    None => return TOKEN_ERROR,
                    Some(_) => (),
                },
                Some('\'') if multiline => match self.peek() {
                    None => return TOKEN_ERROR,
                    Some('\'') => match {
                        self.next_char();
                        self.peek()
                    } {
                        Some('\'') | Some('\\') | Some('$') => {
                            self.next_char();
                        }
                        _ => {
                            self.offset = start;
                            self.pop_ctx();
                            self.push_ctx(Context::StringEnd);
                            return TOKEN_STRING_CONTENT;
                        }
                    },
                    Some(_) => (),
                },
                Some('$') => match self.peek() {
                    Some('$') => {
                        self.next_char();
                    }
                    Some('{') => {
                        self.offset = start;
                        self.push_ctx(Context::InterpolStart);
                        return TOKEN_STRING_CONTENT;
                    }
                    _ => (),
                },
                Some(_) => (),
            }
        }
    }

    fn check_path_since(&mut self, past: usize) -> SyntaxKind {
        self.consume(is_valid_path_char);
        if self.remaining().starts_with("${") {
            self.ctx.push(Context::Path);
        } else if self.str_since(past).ends_with('/') {
            return TOKEN_ERROR;
        }
        TOKEN_PATH
    }

    fn consume_digits(&mut self) -> usize {
        self.consume(|c| c.is_ascii_digit())
    }

    // Consume an optional exponent part; returns false on malformed exponent.
    fn consume_exponent(&mut self) -> bool {
        if let Some('e') | Some('E') = self.peek() {
            self.next_char();
            if let Some('-') | Some('+') = self.peek() {
                self.next_char();
            }
            if self.consume_digits() == 0 {
                return false;
            }
        }
        true
    }

    fn next_inner(&mut self) -> Option<SyntaxKind> {
        let start = self.offset;

        // Handle already started multi-token
        match self.ctx.last().copied() {
            Some(Context::InterpolStart) => {
                self.pop_ctx();
                self.push_ctx(Context::Interpol { brackets: 0 });
                if self.starts_with_bump("${") {
                    return Some(TOKEN_INTERPOL_START);
                } else {
                    unreachable!()
                }
            }
            Some(Context::Path) => {
                if self.starts_with_bump("${") {
                    self.push_ctx(Context::Interpol { brackets: 0 });
                    return Some(TOKEN_INTERPOL_START);
                } else if self.peek().map_or(false, is_valid_path_char) {
                    return Some(self.check_path_since(start));
                } else {
                    self.pop_ctx();
                }
            }
            Some(Context::StringBody { multiline }) => {
                let token = self.next_string(multiline);
                // skip empty stuff
                if self.offset == start {
                    return self.next_inner();
                }
                return Some(token);
            }
            Some(Context::StringEnd) => {
                self.pop_ctx();
                let status = match self.peek() {
                    Some('"') => {
                        self.next_char();
                        true
                    }
                    Some('\'') => match {
                        self.next_char();
                        self.peek()
                    } {
                        Some('\'') => {
                            self.next_char();
                            true
                        }
                        _ => false,
                    },
                    _ => false,
                };

                if !status {
                    return Some(TOKEN_ERROR);
                }

                return Some(TOKEN_STRING_END);
            }
            _ => (),
        }

        if self.consume(char::is_whitespace) > 0 {
            return Some(TOKEN_WHITESPACE);
        }

        if self.peek() == Some('#') {
            self.consume(|c| c != '\n');
            return Some(TOKEN_COMMENT);
        }
        if self.starts_with_bump("/*") {
            loop {
                self.consume(|c| c != '*');
                self.next_char(); // consume the '*', if any
                match self.peek() {
                    None => return Some(TOKEN_ERROR),
                    Some('/') => {
                        self.next_char();
                        return Some(TOKEN_COMMENT);
                    }
                    _ => (),
                }
            }
        }

        if self.starts_with_bump("...") {
            return Some(TOKEN_ELLIPSIS);
        }

        // Check if it's a path
        let store_path = self.peek() == Some('<');
        let kind = {
            let mut lookahead = self.remaining().chars().skip_while(|c| match c {
                '<' | '/' => store_path,
                _ => is_valid_path_char(*c),
            });
            match (lookahead.next(), lookahead.next()) {
                // a//b parses as Update(a, b)
                (Some('/'), Some('/')) => None,
                (Some('/'), Some('*')) => None,
                (Some('/'), Some(c)) if !c.is_whitespace() => Some(IdentType::Path),
                (Some('>'), _) => Some(IdentType::Store),
                (Some(':'), Some(c)) if is_valid_uri_char(c) && !store_path => {
                    Some(IdentType::Uri)
                }
                _ => None,
            }
        };

        let c = self.next_char()?;

        if c == '~' || kind == Some(IdentType::Path) {
            return Some(if c == '~' && self.next_char() != Some('/') {
                TOKEN_ERROR
            } else {
                self.check_path_since(start)
            });
        }

        Some(match c {
            '=' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_EQUAL
            }
            '!' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_NOT_EQUAL
            }
            '!' => TOKEN_INVERT,
            '{' => {
                if let Some(Context::Interpol { brackets }) = self.ctx.last_mut() {
                    *brackets += 1;
                }
                TOKEN_L_BRACE
            }
            '}' => {
                if let Some(Context::Interpol { brackets }) = self.ctx.last_mut() {
                    match brackets.checked_sub(1) {
                        Some(new) => *brackets = new,
                        None => {
                            self.pop_ctx();
                            return Some(TOKEN_INTERPOL_END);
                        }
                    }
                }
                TOKEN_R_BRACE
            }
            '[' => TOKEN_L_BRACK,
            ']' => TOKEN_R_BRACK,
            '@' => TOKEN_AT,
            ':' => TOKEN_COLON,
            ',' => TOKEN_COMMA,
            '.' => {
                if self.peek().map_or(false, |x| x.is_ascii_digit()) {
                    self.consume_digits();
                    if !self.consume_exponent() {
                        return Some(TOKEN_ERROR);
                    }
                    TOKEN_FLOAT
                } else {
                    TOKEN_DOT
                }
            }
            '?' => TOKEN_QUESTION,
            ';' => TOKEN_SEMICOLON,
            '(' => TOKEN_L_PAREN,
            ')' => TOKEN_R_PAREN,
            '+' if self.peek() == Some('+') => {
                self.next_char();
                TOKEN_CONCAT
            }
            '-' if self.peek() == Some('>') => {
                self.next_char();
                TOKEN_IMPLICATION
            }
            '/' if self.peek() == Some('/') => {
                self.next_char();
                TOKEN_UPDATE
            }
            '+' => TOKEN_ADD,
            '-' => TOKEN_SUB,
            '*' => TOKEN_MUL,
            '/' => TOKEN_DIV,
            '<' if kind == Some(IdentType::Store) => {
                self.consume(is_valid_path_char);
                if self.next_char() != Some('>') {
                    return Some(TOKEN_ERROR);
                }
                TOKEN_PATH
            }
            '&' if self.peek() == Some('&') => {
                self.next_char();
                TOKEN_AND_AND
            }
            '|' if self.peek() == Some('|') => {
                self.next_char();
                TOKEN_OR_OR
            }
            '|' if self.peek() == Some('>') => {
                self.next_char();
                TOKEN_PIPE_RIGHT
            }
            '<' if self.peek() == Some('|') => {
                self.next_char();
                TOKEN_PIPE_LEFT
            }
            '<' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_LESS_OR_EQ
            }
            '<' => TOKEN_LESS,
            '>' if self.peek() == Some('=') => {
                self.next_char();
                TOKEN_MORE_OR_EQ
            }
            '>' => TOKEN_MORE,
            '"' => {
                self.push_ctx(Context::StringBody { multiline: false });
                TOKEN_STRING_START
            }
            '\'' if self.peek() == Some('\'') => {
                self.next_char();
                self.push_ctx(Context::StringBody { multiline: true });
                TOKEN_STRING_START
            }
            '0'..='9' => {
                self.consume_digits();
                if self.peek() == Some('.') {
                    self.next_char();
                    self.consume_digits();
                    if !self.consume_exponent() {
                        return Some(TOKEN_ERROR);
                    }
                    TOKEN_FLOAT
                } else {
                    TOKEN_INTEGER
                }
            }
            '$' if self.peek() == Some('{') => {
                self.next_char();
                self.push_ctx(Context::Interpol { brackets: 0 });
                TOKEN_INTERPOL_START
            }
            'a'..='z' | 'A'..='Z' | '_' => {
                let kind = match kind {
                    // It's detected as store if it ends with >, but if it
                    // didn't start with <, that's wrong
                    Some(IdentType::Store) | None => IdentType::Ident,
                    Some(kind) => kind,
                };
                self.consume(|c| match c {
                    'a'..='z' | 'A'..='Z' | '0'..='9' | '_' | '-' | '\'' => true,
                    c => kind == IdentType::Uri && is_valid_uri_char(c),
                });
                match kind {
                    IdentType::Ident => match self.str_since(start) {
                        "assert" => TOKEN_ASSERT,
                        "else" => TOKEN_ELSE,
                        "if" => TOKEN_IF,
                        "in" => TOKEN_IN,
                        "inherit" => TOKEN_INHERIT,
                        "let" => TOKEN_LET,
                        "or" => TOKEN_OR,
                        "rec" => TOKEN_REC,
                        "then" => TOKEN_THEN,
                        "with" => TOKEN_WITH,
                        _ => TOKEN_IDENT,
                    },
                    IdentType::Uri => TOKEN_URI,
                    IdentType::Path => unreachable!(),
                    IdentType::Store => unreachable!(),
                }
            }
            _ => TOKEN_ERROR,
        })
    }
}

impl<'a> Iterator for Tokenizer<'a> {
    type Item = Token;

    fn next(&mut self) -> Option<Token> {
        let start = self.offset;
        self.next_inner().map(|kind| Token { kind, start, end: self.offset })
    }
}
