// A simple concrete syntax tree (green builder + navigable tree).
use crate::syntax::SyntaxKind;

#[derive(Debug)]
pub enum Green {
    Node { kind: SyntaxKind, children: Vec<Green> },
    Token { kind: SyntaxKind, start: usize, end: usize },
}

#[derive(Clone, Copy, Debug)]
pub struct Checkpoint(usize);

pub struct GreenBuilder {
    parents: Vec<(SyntaxKind, usize)>,
    children: Vec<Green>,
}

impl GreenBuilder {
    pub fn new() -> Self {
        GreenBuilder { parents: Vec::new(), children: Vec::new() }
    }

    pub fn token(&mut self, kind: SyntaxKind, start: usize, end: usize) {
        self.children.push(Green::Token { kind, start, end });
    }

    pub fn start_node(&mut self, kind: SyntaxKind) {
        let len = self.children.len();
        self.parents.push((kind, len));
    }

    pub fn finish_node(&mut self) {
        let (kind, first_child) = self.parents.pop().unwrap();
        let children: Vec<Green> = self.children.drain(first_child..).collect();
        self.children.push(Green::Node { kind, children });
    }

    pub fn checkpoint(&self) -> Checkpoint {
        Checkpoint(self.children.len())
    }

    pub fn start_node_at(&mut self, checkpoint: Checkpoint, kind: SyntaxKind) {
        let Checkpoint(checkpoint) = checkpoint;
        assert!(
            checkpoint <= self.children.len(),
            "checkpoint no longer valid, was finish_node called early?"
        );

        if let Some(&(_, first_child)) = self.parents.last() {
            assert!(
                checkpoint >= first_child,
                "checkpoint no longer valid, was an unmatched start_node_at called?"
            );
        }

        self.parents.push((kind, checkpoint));
    }

    pub fn finish(mut self) -> Green {
        assert_eq!(self.children.len(), 1);
        self.children.pop().unwrap()
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Elem {
    Node(usize),
    Token(usize),
}

pub struct NodeData {
    pub kind: SyntaxKind,
    pub start: usize,
    pub end: usize,
    pub parent: Option<usize>,
    pub index_in_parent: usize,
    pub children: Vec<Elem>,
}

pub struct TokenData {
    pub kind: SyntaxKind,
    pub start: usize,
    pub end: usize,
    pub parent: usize,
    pub index_in_parent: usize,
}

pub struct Tree<'a> {
    pub src: &'a str,
    pub nodes: Vec<NodeData>,
    pub tokens: Vec<TokenData>,
}

impl<'a> Tree<'a> {
    pub fn from_green(src: &'a str, green: Green) -> Tree<'a> {
        let mut tree = Tree { src, nodes: Vec::new(), tokens: Vec::new() };
        let mut offset = 0usize;
        tree.add_green(green, None, 0, &mut offset);
        tree
    }

    fn add_green(&mut self, green: Green, parent: Option<usize>, index: usize, offset: &mut usize) -> Elem {
        match green {
            Green::Token { kind, start, end } => {
                let id = self.tokens.len();
                debug_assert_eq!(start, *offset);
                self.tokens.push(TokenData { kind, start, end, parent: parent.unwrap(), index_in_parent: index });
                *offset = end;
                Elem::Token(id)
            }
            Green::Node { kind, children } => {
                let id = self.nodes.len();
                self.nodes.push(NodeData {
                    kind,
                    start: *offset,
                    end: *offset,
                    parent,
                    index_in_parent: index,
                    children: Vec::with_capacity(children.len()),
                });
                let mut elems = Vec::with_capacity(children.len());
                for (i, child) in children.into_iter().enumerate() {
                    elems.push(self.add_green(child, Some(id), i, offset));
                }
                self.nodes[id].children = elems;
                self.nodes[id].end = *offset;
                Elem::Node(id)
            }
        }
    }

    pub fn root(&self) -> usize {
        0
    }

    pub fn kind(&self, node: usize) -> SyntaxKind {
        self.nodes[node].kind
    }

    pub fn node_text(&self, node: usize) -> &'a str {
        let n = &self.nodes[node];
        &self.src[n.start..n.end]
    }

    pub fn token_text(&self, tok: usize) -> &'a str {
        let t = &self.tokens[tok];
        &self.src[t.start..t.end]
    }

    pub fn child_nodes(&self, node: usize) -> impl Iterator<Item = usize> + '_ {
        self.nodes[node].children.iter().filter_map(|e| match e {
            Elem::Node(n) => Some(*n),
            _ => None,
        })
    }

    pub fn child_tokens(&self, node: usize) -> impl Iterator<Item = usize> + '_ {
        self.nodes[node].children.iter().filter_map(|e| match e {
            Elem::Token(t) => Some(*t),
            _ => None,
        })
    }

    pub fn first_child_of_kind(&self, node: usize, kind: SyntaxKind) -> Option<usize> {
        self.child_nodes(node).find(|&c| self.kind(c) == kind)
    }

    pub fn has_child_token(&self, node: usize, kind: SyntaxKind) -> bool {
        self.child_tokens(node).any(|t| self.tokens[t].kind == kind)
    }

    pub fn elem_kind(&self, e: Elem) -> SyntaxKind {
        match e {
            Elem::Node(n) => self.nodes[n].kind,
            Elem::Token(t) => self.tokens[t].kind,
        }
    }

    pub fn elem_range(&self, e: Elem) -> (usize, usize) {
        match e {
            Elem::Node(n) => (self.nodes[n].start, self.nodes[n].end),
            Elem::Token(t) => (self.tokens[t].start, self.tokens[t].end),
        }
    }

    pub fn elem_parent(&self, e: Elem) -> Option<usize> {
        match e {
            Elem::Node(n) => self.nodes[n].parent,
            Elem::Token(t) => Some(self.tokens[t].parent),
        }
    }

    fn elem_index(&self, e: Elem) -> usize {
        match e {
            Elem::Node(n) => self.nodes[n].index_in_parent,
            Elem::Token(t) => self.tokens[t].index_in_parent,
        }
    }

    pub fn prev_sibling_or_token(&self, e: Elem) -> Option<Elem> {
        let parent = self.elem_parent(e)?;
        let idx = self.elem_index(e);
        if idx == 0 {
            None
        } else {
            Some(self.nodes[parent].children[idx - 1])
        }
    }

    pub fn next_sibling_or_token(&self, e: Elem) -> Option<Elem> {
        let parent = self.elem_parent(e)?;
        let idx = self.elem_index(e);
        self.nodes[parent].children.get(idx + 1).copied()
    }

    /// First token (in document order) inside the node.
    pub fn first_token(&self, node: usize) -> Option<usize> {
        for e in &self.nodes[node].children {
            match *e {
                Elem::Token(t) => return Some(t),
                Elem::Node(n) => {
                    if let Some(t) = self.first_token(n) {
                        return Some(t);
                    }
                }
            }
        }
        None
    }
}
