// Parser producing a lossless concrete syntax tree and a list of errors.
use crate::syntax::SyntaxKind::{self, *};
use crate::tokenizer::{Token, Tokenizer};
use crate::tree::{Checkpoint, Green, GreenBuilder};
use std::collections::VecDeque;
use std::fmt;

#[derive(Clone, Debug, PartialEq)]
pub enum ParseError {
    Unexpected(usize, usize),
    UnexpectedExtra(usize, usize),
    UnexpectedWanted(SyntaxKind, usize, usize, Vec<SyntaxKind>),
    UnexpectedDoubleBind(usize, usize),
    UnexpectedEOF,
    UnexpectedEOFWanted(Vec<SyntaxKind>),
    DuplicatedArgs(usize, usize, String),
    RecursionLimitExceeded,
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ParseError::Unexpected(s, e) => write!(f, "error node at {}..{}", s, e),
            ParseError::UnexpectedExtra(s, e) => write!(f, "unexpected token at {}..{}", s, e),
            ParseError::UnexpectedWanted(got, s, e, kinds) => {
                write!(f, "unexpected {:?} at {}..{}, wanted any of {:?}", got, s, e, kinds)
            }
            ParseError::UnexpectedDoubleBind(s, e) => {
                write!(f, "unexpected double bind at {}..{}", s, e)
            }
            ParseError::UnexpectedEOF => write!(f, "unexpected end of file"),
            ParseError::UnexpectedEOFWanted(kinds) => {
                write!(f, "unexpected end of file, wanted any of {:?}", kinds)
            }
            ParseError::DuplicatedArgs(s, e, ident) => {
                write!(f, "argument `{}` is duplicated in {}..{}", ident, s, e)
            }
            ParseError::RecursionLimitExceeded => write!(f, "recursion limit exceeded"),
        }
    }
}

struct Parser<'a> {
    builder: GreenBuilder,
    errors: Vec<ParseError>,
    trivia_buffer: Vec<Token>,
    buffer: VecDeque<Token>,
    iter: Tokenizer<'a>,
    consumed: usize,
    depth: u32,
}

const VAL_WANTED: [SyntaxKind; 6] =
    [TOKEN_L_PAREN, TOKEN_REC, TOKEN_L_BRACE, TOKEN_L_BRACK, TOKEN_STRING_START, TOKEN_IDENT];

impl<'a> Parser<'a> {
    fn new(iter: Tokenizer<'a>) -> Self {
        Parser {
            builder: GreenBuilder::new(),
            errors: Vec::new(),
            trivia_buffer: Vec::with_capacity(1),
            buffer: VecDeque::with_capacity(1),
            iter,
            consumed: 0,
            depth: 0,
        }
    }

    fn get_text_position(&self) -> usize {
        self.consumed
    }

    fn peek_raw(&mut self) -> Option<Token> {
        if self.buffer.is_empty() {
            if let Some(token) = self.iter.next() {
                self.buffer.push_back(token);
            }
        }
        self.buffer.front().copied()
    }

    fn drain_trivia_buffer(&mut self) {
        for t in self.trivia_buffer.drain(..) {
            self.consumed += t.end - t.start;
            self.builder.token(t.kind, t.start, t.end);
        }
    }

    fn eat_trivia(&mut self) {
        self.peek();
        self.drain_trivia_buffer();
    }

    fn start_node(&mut self, kind: SyntaxKind) {
        self.eat_trivia();
        self.builder.start_node(kind);
    }

    fn checkpoint(&mut self) -> Checkpoint {
        self.eat_trivia();
        self.builder.checkpoint()
    }

    fn start_node_at(&mut self, checkpoint: Checkpoint, kind: SyntaxKind) {
        self.builder.start_node_at(checkpoint, kind);
    }

    fn finish_node(&mut self) {
        self.builder.finish_node();
    }

    fn start_error_node(&mut self) -> usize {
        self.start_node(NODE_ERROR);
        self.get_text_position()
    }

    fn finish_error_node(&mut self) -> usize {
        self.finish_node();
        self.get_text_position()
    }

    fn bump(&mut self) {
        match self.try_next() {
            Some(token) => {
                if token.kind.is_trivia() {
                    self.trivia_buffer.push(token)
                } else {
                    self.drain_trivia_buffer();
                    self.manual_bump(token, token.kind);
                }
            }
            None => self.errors.push(ParseError::UnexpectedEOF),
        }
    }

    fn try_next(&mut self) -> Option<Token> {
        self.buffer.pop_front().or_else(|| self.iter.next())
    }

    fn manual_bump(&mut self, token: Token, kind: SyntaxKind) {
        self.consumed += token.end - token.start;
        self.builder.token(kind, token.start, token.end);
    }

    fn peek_data(&mut self) -> Option<Token> {
        while self.peek_raw().map(|t| t.kind.is_trivia()).unwrap_or(false) {
            self.bump();
        }
        self.peek_raw()
    }

    fn peek(&mut self) -> Option<SyntaxKind> {
        self.peek_data().map(|t| t.kind)
    }

    fn expect_peek_any(&mut self, allowed: &[SyntaxKind]) -> Option<SyntaxKind> {
        let next = match self.peek() {
            None => None,
            Some(kind) if allowed.contains(&kind) => Some(kind),
            Some(kind) => {
                let start = self.start_error_node();
                loop {
                    self.bump();
                    if self.peek().map(|kind| allowed.contains(&kind)).unwrap_or(true) {
                        break;
                    }
                }
                let end = self.finish_error_node();
                self.errors.push(ParseError::UnexpectedWanted(kind, start, end, allowed.to_vec()));

                self.peek()
            }
        };

        if next.is_none() {
            self.errors.push(ParseError::UnexpectedEOFWanted(allowed.to_vec()));
        }

        next
    }

    fn expect(&mut self, expected: SyntaxKind) {
        if self.expect_peek_any(&[expected]).is_some() {
            self.bump();
        }
    }

    fn expect_ident(&mut self) {
        if self.expect_peek_any(&[TOKEN_IDENT]).is_some() {
            self.start_node(NODE_IDENT);
            self.bump();
            self.finish_node()
        }
    }

    fn parse_dynamic(&mut self) {
        self.start_node(NODE_DYNAMIC);
        self.bump();
        while self.peek().map(|t| t != TOKEN_INTERPOL_END).unwrap_or(false) {
            self.parse_expr();
        }
        self.bump();
        self.finish_node();
    }

    fn parse_string(&mut self) {
        self.start_node(NODE_STRING);
        self.expect(TOKEN_STRING_START);

        loop {
            match self.expect_peek_any(&[TOKEN_STRING_END, TOKEN_STRING_CONTENT, TOKEN_INTERPOL_START]) {
                Some(TOKEN_STRING_CONTENT) => self.bump(),
                Some(TOKEN_INTERPOL_START) => {
                    self.start_node(NODE_INTERPOL);
                    self.bump();
                    self.parse_expr();
                    self.expect(TOKEN_INTERPOL_END);
                    self.finish_node();
                }
                // handled by expect_peek_any
                _ => break,
            }
        }
        self.expect(TOKEN_STRING_END);

        self.finish_node();
    }

    fn parse_attr(&mut self) {
        match self.peek() {
            Some(TOKEN_INTERPOL_START) => self.parse_dynamic(),
            Some(TOKEN_STRING_START) => self.parse_string(),
            _ => {
                if self.expect_peek_any(&[TOKEN_IDENT, TOKEN_OR]).is_some() {
                    self.start_node(NODE_IDENT);
                    let token = self.try_next().unwrap();
                    self.manual_bump(token, TOKEN_IDENT);
                    self.finish_node()
                }
            }
        }
    }

    fn parse_attrpath(&mut self) {
        self.start_node(NODE_ATTRPATH);
        loop {
            self.parse_attr();

            if self.peek() == Some(TOKEN_DOT) {
                self.bump();
            } else {
                break;
            }
        }
        self.finish_node();
    }

    fn parse_pattern(&mut self, bound: bool) {
        // currently at TOKEN_L_BRACE
        if self.peek().map(|t| t == TOKEN_R_BRACE).unwrap_or(true) {
            self.bump();
        } else {
            loop {
                match self.expect_peek_any(&[TOKEN_R_BRACE, TOKEN_ELLIPSIS, TOKEN_IDENT]) {
                    Some(TOKEN_R_BRACE) => {
                        self.bump();
                        break;
                    }
                    Some(TOKEN_ELLIPSIS) => {
                        self.bump();
                        self.expect(TOKEN_R_BRACE);
                        break;
                    }
                    Some(TOKEN_IDENT) => {
                        self.start_node(NODE_PAT_ENTRY);

                        self.expect_ident();

                        if let Some(TOKEN_QUESTION) = self.peek() {
                            self.bump();
                            self.parse_expr();
                        }
                        self.finish_node();

                        match self.peek() {
                            Some(TOKEN_COMMA) => self.bump(),
                            _ => {
                                self.expect(TOKEN_R_BRACE);
                                break;
                            }
                        }
                    }
                    // handled by expect_peek_any
                    _ => break,
                }
            }
        }

        if self.peek() == Some(TOKEN_AT) {
            let kind = if bound { NODE_ERROR } else { NODE_PAT_BIND };
            self.start_node(kind);
            let start = self.get_text_position();
            self.bump();
            self.expect_ident();
            let end = self.finish_error_node();
            if bound {
                self.errors.push(ParseError::UnexpectedDoubleBind(start, end));
            }
        }
    }

    fn parse_set(&mut self, until: SyntaxKind) {
        loop {
            match self.peek() {
                None => break,
                token if token == Some(until) => break,
                Some(TOKEN_INHERIT) => {
                    self.start_node(NODE_INHERIT);
                    self.bump();

                    if self.peek() == Some(TOKEN_L_PAREN) {
                        self.start_node(NODE_INHERIT_FROM);
                        self.bump();
                        self.parse_expr();
                        self.expect(TOKEN_R_PAREN);
                        self.finish_node();
                    }

                    loop {
                        match self.peek() {
                            Some(t) if t != TOKEN_SEMICOLON => {
                                self.parse_attr();
                            }
                            Some(_) => {
                                break;
                            }
                            None => {
                                self.errors.push(ParseError::UnexpectedEOF);
                                break;
                            }
                        }
                    }

                    self.expect(TOKEN_SEMICOLON);
                    self.finish_node();
                }
                Some(_) => {
                    self.start_node(NODE_ATTRPATH_VALUE);
                    self.parse_attrpath();
                    self.expect(TOKEN_ASSIGN);
                    self.parse_expr();
                    self.expect(TOKEN_SEMICOLON);
                    self.finish_node();
                }
            }
        }
        self.bump(); // the final close, like '}'
    }

    fn parse_path(&mut self) {
        self.start_node(NODE_PATH);
        self.bump();
        loop {
            match self.peek_raw().map(|t| t.kind) {
                Some(TOKEN_PATH) => self.bump(),
                Some(TOKEN_INTERPOL_START) => {
                    self.start_node(NODE_INTERPOL);
                    self.bump();
                    self.parse_expr();
                    self.expect(TOKEN_INTERPOL_END);
                    self.finish_node();
                }
                _ => break,
            }
        }
        self.finish_node();
    }

    fn parse_val(&mut self) -> Checkpoint {
        let peek = match self.peek() {
            None => {
                self.errors.push(ParseError::UnexpectedEOF);
                return self.checkpoint();
            }
            Some(it) => it,
        };
        let checkpoint = self.checkpoint();
        match peek {
            TOKEN_L_PAREN => {
                self.start_node(NODE_PAREN);
                self.bump();
                self.parse_expr();
                self.bump();
                self.finish_node();
            }
            TOKEN_REC => {
                self.start_node(NODE_ATTR_SET);
                self.bump();
                self.expect(TOKEN_L_BRACE);
                self.parse_set(TOKEN_R_BRACE);
                self.finish_node();
            }
            TOKEN_L_BRACE => {
                // Do a lookahead:
                let mut peek = [None, None];
                for i in &mut peek {
                    let kind = loop {
                        match self.iter.next() {
                            Some(token) => {
                                self.buffer.push_back(token);
                                if !token.kind.is_trivia() {
                                    break Some(token.kind);
                                }
                            }
                            None => break None,
                        }
                    };
                    *i = kind;
                }

                match peek {
                    [Some(TOKEN_IDENT), Some(TOKEN_COMMA)]
                    | [Some(TOKEN_IDENT), Some(TOKEN_QUESTION)]
                    | [Some(TOKEN_IDENT), Some(TOKEN_R_BRACE)]
                    | [Some(TOKEN_ELLIPSIS), Some(TOKEN_R_BRACE)]
                    | [Some(TOKEN_R_BRACE), Some(TOKEN_COLON)]
                    | [Some(TOKEN_R_BRACE), Some(TOKEN_AT)] => {
                        // This looks like a pattern
                        self.start_node(NODE_LAMBDA);

                        self.start_node(NODE_PATTERN);
                        self.bump();
                        self.parse_pattern(false);
                        self.finish_node();

                        self.expect(TOKEN_COLON);
                        self.parse_expr();

                        self.finish_node();
                    }
                    _ => {
                        // This looks like a set
                        self.start_node(NODE_ATTR_SET);
                        self.bump();
                        self.parse_set(TOKEN_R_BRACE);
                        self.finish_node();
                    }
                }
            }
            TOKEN_L_BRACK => {
                self.start_node(NODE_LIST);
                self.bump();
                while self.peek().map(|t| t != TOKEN_R_BRACK).unwrap_or(false) {
                    self.parse_val();
                }
                self.bump();
                self.finish_node();
            }
            TOKEN_STRING_START => self.parse_string(),
            TOKEN_PATH => self.parse_path(),
            t if t.is_literal() => {
                self.start_node(NODE_LITERAL);
                self.bump();
                self.finish_node();
            }
            TOKEN_IDENT => {
                self.expect_ident();

                match self.peek() {
                    Some(TOKEN_COLON) => {
                        self.start_node_at(checkpoint, NODE_LAMBDA);
                        self.start_node_at(checkpoint, NODE_IDENT_PARAM);
                        self.finish_node();
                        self.bump();
                        self.parse_expr();
                        self.finish_node();
                    }
                    Some(TOKEN_AT) => {
                        self.start_node_at(checkpoint, NODE_LAMBDA);
                        self.start_node_at(checkpoint, NODE_PATTERN);
                        self.start_node_at(checkpoint, NODE_PAT_BIND);
                        self.bump();
                        self.finish_node(); // PatBind

                        self.expect(TOKEN_L_BRACE);
                        self.parse_pattern(true);
                        self.finish_node(); // Pattern

                        self.expect(TOKEN_COLON);
                        self.parse_expr();
                        self.finish_node(); // Lambda
                    }
                    _ => (),
                }
            }
            kind => {
                let start = self.start_error_node();
                self.bump();
                let end = self.finish_error_node();
                self.errors.push(ParseError::UnexpectedWanted(kind, start, end, VAL_WANTED.to_vec()));
            }
        };

        if self.peek() == Some(TOKEN_DOT) {
            self.start_node_at(checkpoint, NODE_SELECT);
            self.bump();
            self.parse_attrpath();
            if self.peek() == Some(TOKEN_OR) {
                self.bump();
                self.parse_val();
            }
            self.finish_node();
        } else if self.peek() == Some(TOKEN_OR) {
            // `or` is allowed as an identifier when used as an argument
            self.start_node_at(checkpoint, NODE_APPLY);
            self.start_node(NODE_IDENT);
            let token = self.try_next().unwrap();
            self.manual_bump(token, TOKEN_IDENT);
            self.finish_node();
            self.finish_node();
        }

        checkpoint
    }

    fn parse_left_assoc(&mut self, next: fn(&mut Self) -> Checkpoint, ops: &[SyntaxKind]) -> Checkpoint {
        let checkpoint = next(self);
        while self.peek().map(|t| ops.contains(&t)).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_BIN_OP);
            self.bump();
            next(self);
            self.finish_node();
        }
        checkpoint
    }

    fn parse_right_assoc(&mut self, next: fn(&mut Self) -> Checkpoint, ops: &[SyntaxKind]) -> Checkpoint {
        let checkpoint = next(self);
        if self.peek().map(|t| ops.contains(&t)).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_BIN_OP);
            self.bump();
            self.parse_right_assoc(next, ops);
            self.finish_node();
        }
        checkpoint
    }

    fn parse_single(&mut self, next: fn(&mut Self) -> Checkpoint, ops: &[SyntaxKind]) -> Checkpoint {
        let checkpoint = next(self);
        if self.peek().map(|t| ops.contains(&t)).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_BIN_OP);
            self.bump();
            next(self);
            self.finish_node();
        }
        checkpoint
    }

    fn parse_fn(&mut self) -> Checkpoint {
        let checkpoint = self.parse_val();

        while self.peek().map(|t| t.is_fn_arg()).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_APPLY);
            self.parse_val();
            self.finish_node();
        }

        checkpoint
    }

    fn parse_negate(&mut self) -> Checkpoint {
        if self.peek() == Some(TOKEN_SUB) {
            let checkpoint = self.checkpoint();
            self.start_node(NODE_UNARY_OP);
            self.bump();
            self.parse_negate();
            self.finish_node();
            checkpoint
        } else {
            self.parse_fn()
        }
    }

    fn parse_hasattr(&mut self) -> Checkpoint {
        let checkpoint = self.parse_negate();
        while self.peek().map(|t| t == TOKEN_QUESTION).unwrap_or(false) {
            self.start_node_at(checkpoint, NODE_HAS_ATTR);
            self.bump();
            self.parse_attrpath();
            self.finish_node();
        }
        checkpoint
    }

    fn parse_concat(&mut self) -> Checkpoint {
        self.parse_right_assoc(Self::parse_hasattr, &[TOKEN_CONCAT])
    }

    fn parse_mul(&mut self) -> Checkpoint {
        self.parse_left_assoc(Self::parse_concat, &[TOKEN_MUL, TOKEN_DIV])
    }

    fn parse_add(&mut self) -> Checkpoint {
        self.parse_left_assoc(Self::parse_mul, &[TOKEN_ADD, TOKEN_SUB])
    }

    fn parse_invert(&mut self) -> Checkpoint {
        if self.peek() == Some(TOKEN_INVERT) {
            let checkpoint = self.checkpoint();
            self.start_node(NODE_UNARY_OP);
            self.bump();
            self.parse_invert();
            self.finish_node();
            checkpoint
        } else {
            self.parse_add()
        }
    }

    fn parse_update(&mut self) -> Checkpoint {
        self.parse_right_assoc(Self::parse_invert, &[TOKEN_UPDATE])
    }

    fn parse_compare(&mut self) -> Checkpoint {
        self.parse_single(
            Self::parse_update,
            &[TOKEN_LESS, TOKEN_LESS_OR_EQ, TOKEN_MORE, TOKEN_MORE_OR_EQ],
        )
    }

    fn parse_equal(&mut self) -> Checkpoint {
        self.parse_single(Self::parse_compare, &[TOKEN_EQUAL, TOKEN_NOT_EQUAL])
    }

    fn parse_and(&mut self) -> Checkpoint {
        self.parse_left_assoc(Self::parse_equal, &[TOKEN_AND_AND])
    }

    fn parse_or(&mut self) -> Checkpoint {
        self.parse_left_assoc(Self::parse_and, &[TOKEN_OR_OR])
    }

    fn parse_implication(&mut self) -> Checkpoint {
        self.parse_right_assoc(Self::parse_or, &[TOKEN_IMPLICATION])
    }

    fn parse_pipe_right(&mut self) -> Checkpoint {
        self.parse_left_assoc(Self::parse_implication, &[TOKEN_PIPE_RIGHT])
    }

    fn parse_pipe_left(&mut self) -> Checkpoint {
        self.parse_right_assoc(Self::parse_pipe_right, &[TOKEN_PIPE_LEFT])
    }

    fn parse_math(&mut self) -> Checkpoint {
        self.parse_pipe_left()
    }

    fn parse_expr(&mut self) -> Checkpoint {
        // Limit chaos
        if self.depth >= 512 {
            self.errors.push(ParseError::RecursionLimitExceeded);
            // Consume all remaining tokens
            while self.peek().is_some() {
                self.bump()
            }
            return self.checkpoint();
        }
        self.depth += 1;
        let out = match self.peek() {
            Some(TOKEN_LET) => {
                let checkpoint = self.checkpoint();
                self.bump();

                if self.peek() == Some(TOKEN_L_BRACE) {
                    self.start_node_at(checkpoint, NODE_LEGACY_LET);
                    self.bump();
                    self.parse_set(TOKEN_R_BRACE);
                    self.finish_node();
                } else {
                    self.start_node_at(checkpoint, NODE_LET_IN);
                    self.parse_set(TOKEN_IN);
                    self.parse_expr();
                    self.finish_node();
                }

                checkpoint
            }
            Some(TOKEN_WITH) => {
                let checkpoint = self.checkpoint();
                self.start_node(NODE_WITH);
                self.bump();
                self.parse_expr();
                self.expect(TOKEN_SEMICOLON);
                self.parse_expr();
                self.finish_node();
                checkpoint
            }
            Some(TOKEN_IF) => {
                let checkpoint = self.checkpoint();
                self.start_node(NODE_IF_ELSE);
                self.bump();
                self.parse_expr();
                self.expect(TOKEN_THEN);
                self.parse_expr();
                self.expect(TOKEN_ELSE);
                self.parse_expr();
                self.finish_node();
                checkpoint
            }
            Some(TOKEN_ASSERT) => {
                let checkpoint = self.checkpoint();
                self.start_node(NODE_ASSERT);
                self.bump();
                self.parse_expr();
                self.expect(TOKEN_SEMICOLON);
                self.parse_expr();
                self.finish_node();
                checkpoint
            }
            _ => self.parse_math(),
        };
        self.depth -= 1;
        out
    }
}

pub fn parse(input: &str) -> (Green, Vec<ParseError>) {
    let mut parser = Parser::new(Tokenizer::new(input));
    parser.builder.start_node(NODE_ROOT);
    parser.parse_expr();
    parser.eat_trivia();
    if parser.peek().is_some() {
        let start = parser.start_error_node();
        while parser.peek().is_some() {
            parser.bump();
        }
        let end = parser.finish_error_node();
        parser.errors.push(ParseError::UnexpectedExtra(start, end));
        parser.eat_trivia();
    }
    parser.builder.finish_node();
    (parser.builder.finish(), parser.errors)
}
