    pub binding: Binding,
    pub used: bool,
}

impl DeadCode {
    pub fn message(&self) -> String {
        let prefix = if self.used { "Used" } else { "Unused" };
        let what = match self.scope.kind {
            ScopeKind::LambdaPattern => "lambda pattern",
            ScopeKind::LambdaArg => "lambda argument",
            ScopeKind::LetIn => "let binding",
            ScopeKind::RecAttrSet => "recursive attrset binding",
        };
