    while idx > 0 {
        idx -= 1;
        let tok = &tree.tokens[idx];
        match tok.kind {
            TOKEN_WHITESPACE => {
                line_breaks += tree.token_text(idx).matches('\n').count();
                if line_breaks > 1 {
                    return false;
                }
            }
            TOKEN_COMMENT => {
                if tree.token_text(idx).contains("deadnix: skip") {
                    return true;
                }
            }
            _ => {}
        }
    }
    false
}

impl Settings {
    pub fn find_dead_code(&self, tree: &Tree) -> Vec<DeadCode> {
        // collect scopes in preorder
        let mut scopes = Vec::new();
        let mut stack = vec![tree.root()];
        while let Some(node) = stack.pop() {
            if let Some(scope) = Scope::new(tree, node) {
                scopes.push(scope);
            }
            let children: Vec<usize> = tree.child_nodes(node).collect();
            for c in children.into_iter().rev() {
                stack.push(c);
            }
        }

        struct Prepared {
            scope: Scope,
            bindings: Vec<Binding>,
            bodies: Vec<Body>,
        }
        let mut prepared = Vec::new();
        for scope in scopes {
            if scope.kind == ScopeKind::RecAttrSet {
                continue;
            }
            let bindings: Vec<Binding> = scope
                .bindings(tree)
                .into_iter()
                .filter(|b| b.mortal)
                .filter(|b| !(self.no_lambda_arg && scope.kind == ScopeKind::LambdaArg))
                .filter(|b| {
                    !(self.no_lambda_pattern_names
                        && scope.kind == ScopeKind::LambdaPattern
                        && tree.kind(b.decl_node) == NODE_PAT_ENTRY)
                })
                .filter(|b| !(self.no_underscore && b.name.starts_with('_')))
                .filter(|b| !has_pragma_skip(tree, b.name_node))
                .collect();
            if bindings.is_empty() {
                continue;
            }
            let bodies = scope.bodies(tree);
            prepared.push(Prepared { scope, bindings, bodies });
        }

        let mut results: HashMap<usize, DeadCode> = HashMap::new();
        loop {
            let prev_len = results.len();
            for p in &prepared {
                for binding in &p.bindings {
                    let used = p.bodies.iter().any(|body| {
                        if body.own == Some(binding.decl_node) {
                            return false;
                        }
                        let dead = match &body.dead {
                            BodyDead::Never => false,
                            BodyDead::Entry(ident) => results.contains_key(ident),
                            BodyDead::Inherit(attrs) => attrs
                                .iter()
                                .all(|a| a.map_or(false, |id| results.contains_key(&id))),
                        };
                        !dead && find_usage(tree, &binding.name, body.node)
                    });
                    if !used {
                        results.insert(
                            binding.name_node,
                            DeadCode { scope: p.scope.clone(), binding: binding.clone(), used: false },
                        );
                    } else if self.warn_used_underscore && binding.name.starts_with('_') {
                        results.insert(
                            binding.name_node,
                            DeadCode { scope: p.scope.clone(), binding: binding.clone(), used: true },
                        );
                    }
                }
            }
            if results.len() == prev_len {
                break;
            }
        }

        let mut results: Vec<DeadCode> = results.into_values().collect();
        results.sort_by_key(|r| tree.nodes[r.binding.name_node].start);
        results
    }
}
