        // split inclusive on line separators
        let mut pieces: Vec<&str> = Vec::new();
        let mut last = 0;
        for (i, c) in text.char_indices() {
            if is_line_sep(c) {
                let end = i + c.len_utf8();
                pieces.push(&text[last..end]);
                last = end;
            }
        }
        if last < text.len() {
            pieces.push(&text[last..]);
        }

        let mut char_offset = 0;
        let mut byte_offset = 0;
        let mut last_line: Option<(Line, bool)> = None;
        let mut lines = Vec::new();
        for piece in pieces {
            if let Some((last, ends_with_cr)) = last_line.as_mut() {
                if *ends_with_cr && piece == "\n" {
                    last.char_len += 1;
                    last.byte_len += 1;
                    char_offset += 1;
                    byte_offset += 1;
                    let (l, _) = last_line.take().unwrap();
                    lines.push(l);
                    continue;
                }
            }
            let char_len = piece.chars().count();
            let ends_with_cr = piece.ends_with('\r');
            let line = Line { offset: char_offset, char_len, byte_offset, byte_len: piece.len() };
            char_offset += char_len;
            byte_offset += piece.len();
            if let Some((l, _)) = last_line.replace((line, ends_with_cr)) {
                lines.push(l);
            }
        }
        if let Some((l, _)) = last_line {
            lines.push(l);
        }
        Source { text, lines, len: char_offset, byte_len: byte_offset }
    }

    fn line_text(&self, line: &Line) -> &'a str {
        &self.text[line.byte_offset..line.byte_offset + line.byte_len]
    }

    fn get_offset_line(&self, offset: usize) -> Option<(Line, usize, usize)> {
        if offset <= self.len {
            let idx = match self.lines.binary_search_by_key(&offset, |l| l.offset) {
                Ok(i) => i,
                Err(i) => i.saturating_sub(1),
            };
            let line = *self.lines.get(idx)?;
            Some((line, idx, offset - line.offset))
        } else {
            None
        }
    }

    fn get_byte_line(&self, byte_offset: usize) -> Option<(Line, usize, usize)> {
        if byte_offset <= self.byte_len {
            let idx = match self.lines.binary_search_by_key(&byte_offset, |l| l.byte_offset) {
                Ok(i) => i,
                Err(i) => i.saturating_sub(1),
            };
            let line = *self.lines.get(idx)?;
            Some((line, idx, byte_offset - line.byte_offset))
        } else {
            None
        }
    }

    fn get_line_range(&self, start: usize, end: usize) -> (usize, usize) {
        let s = self.get_offset_line(start).map_or(0, |(_, l, _)| l);
        let e = self
            .get_offset_line(end.saturating_sub(1).max(start))
            .map_or(self.lines.len(), |(_, l, _)| l + 1);
        (s, e)
    }
}

fn char_width(c: char, col: usize) -> (char, usize) {
    match c {
        '\t' => {
            let tab_end = (col / TAB_WIDTH + 1) * TAB_WIDTH;
            (' ', tab_end - col)
        }
        c if c.is_whitespace() => (' ', 1),
        _ => (c, width::char_width(c).unwrap_or(1)),
    }
}

struct LabelInfo {
    start: usize, // char span
    end: usize,
    msg: String,
    color: Color,
    order: i32,
    multiline: bool,
}

struct LineLabel<'l> {
    col: usize,
    label: &'l LabelInfo,
}

fn binding_color(kind: ScopeKind) -> Color {
    match kind {
        ScopeKind::LambdaArg => Color::Cyan,
        ScopeKind::LambdaPattern => Color::Magenta,
        ScopeKind::LetIn => Color::Red,
        ScopeKind::RecAttrSet => Color::Yellow,
    }
}

pub fn render(file: &str, content: &str, tree: &Tree, results: &[DeadCode], color: bool) -> String {
    let p = Painter { enabled: color };
    let src = Source::new(content);
    let mut out = String::new();

    // header
    out.push_str(&p.paint("Warning:", Some(Color::Yellow)));
    out.push(' ');
    out.push_str("Unused declarations were found.");
    out.push('\n');

    // labels
    let mut labels: Vec<LabelInfo> = Vec::new();
    let mut order = 0i32;
    for result in results {
        let n = &tree.nodes[result.binding.name_node];
        let (bstart, bend) = (n.start, n.end);
        let lab = (|| {
            let (start_line, start_line_idx, start_byte_col) = src.get_byte_line(bstart)?;
            let line_text = src.line_text(&start_line);
            let num_chars_before_start = line_text
                .get(..start_byte_col.min(line_text.len()))
                .map(|s| s.chars().count())
                .unwrap_or(0);
            let start_char = start_line.offset + num_chars_before_start;
            if bstart >= bend {
                Some((start_char, start_char, false))
            } else {
                let (end_line, end_line_idx, end_byte_col) = src.get_byte_line(bend - 1)?;
                let end_text = src.line_text(&end_line);
                let n = end_text.get(..end_byte_col + 1).map(|s| s.chars().count()).unwrap_or(0);
                Some((start_char, end_line.offset + n, start_line_idx != end_line_idx))
            }
        })();
        if let Some((s, e, multi)) = lab {
            labels.push(LabelInfo {
                start: s,
                end: e,
                msg: result.message(),
                color: binding_color(result.scope.kind),
                order,
                multiline: multi,
            });
        }
        order -= 1;
    }

    if labels.is_empty() {
        return out;
    }

    let span_start = labels.iter().map(|l| l.start).min().unwrap();
    let span_end = labels.iter().map(|l| l.end).max().unwrap();
    let (line_start, line_end) = src.get_line_range(span_start, span_end);

    let mut line_no_width = 1usize;
    {
        let mut x = 10u64;
        while (line_end as u64) / x != 0 {
            line_no_width += 1;
            x *= 10;
        }
    }

    // location
    let location = tree.nodes[results[0].binding.name_node].start;
    let (line_no, col_no) = match src.get_offset_line(location) {
        Some((_, idx, col)) => (format!("{}", idx + 1), format!("{}", col + 1)),
        None => ("?".to_string(), "?".to_string()),
    };
    out.push_str(&" ".repeat(line_no_width + 2));
    out.push_str(&p.paint("╭", Some(MARGIN_COLOR)));
    out.push_str(&p.paint("─", Some(MARGIN_COLOR)));
    out.push_str(&p.paint("[", Some(MARGIN_COLOR)));
    out.push_str(file);
    out.push_str(&format!(":{}:{}", line_no, col_no));
    out.push_str(&p.paint("]", Some(MARGIN_COLOR)));
    out.push('\n');

    for idx in line_start..line_end {
        let line = match src.lines.get(idx) {
            Some(l) => *l,
            None => continue,
        };
        let line_span_start = line.offset;
        let line_span_end = line.offset + line.char_len;

        let mut line_labels: Vec<LineLabel> = Vec::new();
        for label in labels.iter() {
            if label.start >= line_span_start && label.end <= line_span_end && !label.multiline {
                let col = ((label.start + label.end) / 2).max(label.start) - line.offset;
                line_labels.push(LineLabel { col, label });
            }
        }
        if line_labels.is_empty() {
            continue;
        }

        line_labels.sort_by_key(|ll| (ll.label.order, ll.col, !ll.label.start));

        let arrow_len = line_labels.iter().fold(0, |l, ll| l.max(ll.label.end - line.offset)) + 1;

        // margin
        let line_no = format!("{}", idx + 1);
        out.push(' ');
        out.push_str(&p.paint(
            &format!("{}{} │", " ".repeat(line_no_width - line_no.chars().count()), line_no),
            Some(MARGIN_COLOR),
        ));

        let text = src.line_text(&line).trim_end();
        let get_highlight = |col: usize| -> Option<&LabelInfo> {
            line_labels
                .iter()
                .map(|ll| ll.label)
                .filter(|l| l.start <= line.offset + col && line.offset + col < l.end)
                .min_by_key(|l| l.end - l.start)
        };
        for (col, c) in text.chars().enumerate() {
            let color = match get_highlight(col) {
                Some(h) => h.color,
                None => UNIMPORTANT_COLOR,
            };
            let (c, w) = char_width(c, col);
            if c.is_whitespace() {
                for _ in 0..w {
                    out.push_str(&p.paint_char(c, Some(color)));
                }
            } else {
                out.push_str(&p.paint_char(c, Some(color)));
            }
        }
        out.push('\n');

        for row in 0..line_labels.len() {
            let line_label = &line_labels[row];
            out.push(' ');
            out.push_str(&p.paint(&format!("{}│", " ".repeat(line_no_width + 1)), Some(SKIPPED_MARGIN_COLOR)));

            let mut chars = text.chars();
            for col in 0..arrow_len {
                let w = chars.next().map_or(1, |c| char_width(c, col).1);
                let is_hbar = col > line_label.col;
                let lcolor = Some(line_label.label.color);
                let (c, tail): (String, String) = if col == line_label.col {
                    (p.paint("╰", lcolor), p.paint("─", lcolor))
                } else if let Some(vbar_ll) = line_labels
                    .iter()
                    .enumerate()
                    .find(|(j, ll)| ll.col == col && row <= *j)
                    .map(|(_, ll)| ll)
                {
                    if is_hbar {
                        (p.paint("─", lcolor), p.paint("─", lcolor))
                    } else {
                        (p.paint("│", Some(vbar_ll.label.color)), p.paint(" ", lcolor))
                    }
                } else if is_hbar {
                    (p.paint("─", lcolor), p.paint("─", lcolor))
                } else {
                    (" ".to_string(), " ".to_string())
                };
                if w > 0 {
                    out.push_str(&c);
                }
                for _ in 1..w {
                    out.push_str(&tail);
                }
            }
            out.push(' ');
            out.push_str(&line_label.label.msg);
            out.push('\n');
        }
    }
    out
}

pub fn json_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\x08' => out.push_str("\\b"),
            '\x0C' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn json_results(file: &str, content: &str, tree: &Tree, results: &[DeadCode]) -> String {
    let mut items = Vec::new();
    for result in results {
        let n = &tree.nodes[result.binding.name_node];
        let start = n.start;
        let end = n.end;
        let before = &content[..start];
        let line = before.matches('\n').count() + 1;
        let line_start = before.rfind('\n').map(|i| i + 1).unwrap_or(0);
        let column = start - line_start + 1;
        let end_column = end - line_start + 1;
        items.push(format!(
            "{{\"column\":{},\"endColumn\":{},\"line\":{},\"message\":{}}}",
            column,
            end_column,
            line,
            json_escape(&result.message())
        ));
    }
    format!("{{\"file\":{},\"results\":[{}]}}", json_escape(file), items.join(","))
}

pub fn json_messages(file: &str, messages: &[String]) -> String {
    let items: Vec<String> =
        messages.iter().map(|m| format!("{{\"message\":{}}}", json_escape(m))).collect();
    format!("{{\"file\":{},\"results\":[{}]}}", json_escape(file), items.join(","))
}
