}

struct Editor<'t, 'a> {
    tree: &'t Tree<'a>,
    dead: HashSet<usize>,
    edits: Vec<Edit>,
}

impl<'t, 'a> Editor<'t, 'a> {
    fn is_ws(&self, e: Option<Elem>) -> bool {
        e.map_or(false, |e| self.tree.elem_kind(e) == TOKEN_WHITESPACE)
    }

    fn remove(&mut self, start: usize, end: usize) {
        self.edits.push(Edit { start, end, replacement: String::new() });
    }

    /// Remove a node together with the whitespace directly preceding it
    fn remove_with_prev_ws(&mut self, node: usize) {
        let tree = self.tree;
        let mut start = tree.nodes[node].start;
        let end = tree.nodes[node].end;
        let prev = tree.prev_sibling_or_token(Elem::Node(node));
        if self.is_ws(prev) {
            start = tree.elem_range(prev.unwrap()).0;
        }
        self.remove(start, end);
    }

    fn entry_dead(&self, entry: usize) -> bool {
        entry_name(self.tree, entry).map_or(false, |id| self.dead.contains(&id))
    }

    fn inherit_dead(&self, inherit: usize) -> bool {
        self.tree.child_nodes(inherit).filter(|&c| is_attr_kind(self.tree.kind(c))).all(|c| {
            self.tree.kind(c) == NODE_IDENT && self.dead.contains(&c)
        })
    }

    fn scan(&mut self, node: usize) {
        let tree = self.tree;
        match Scope::new(tree, node) {
            Some(scope) if scope.kind == ScopeKind::LetIn => {
                let entries: Vec<usize> = scope.entries(tree).collect();
                let inherits: Vec<usize> = scope.inherits(tree).collect();
                let all_dead = entries.iter().all(|&e| self.entry_dead(e))
                    && inherits.iter().all(|&i| self.inherit_dead(i));
                if all_dead {
                    if let Some(body) = scope.body {
                        self.remove(tree.nodes[node].start, tree.nodes[body].start);
                        self.scan(body);
                    }
                    return;
                }
                let children: Vec<usize> = tree.child_nodes(node).collect();
                for child in children {
                    match tree.kind(child) {
                        NODE_ATTRPATH_VALUE => {
                            if self.entry_dead(child) {
                                self.remove_with_prev_ws(child);
                            } else {
                                self.scan(child);
                            }
                        }
                        NODE_INHERIT => {
                            if self.inherit_dead(child) {
                                self.remove_with_prev_ws(child);
                            } else {
                                let attrs: Vec<usize> = tree.child_nodes(child).collect();
                                for attr in attrs {
                                    if tree.kind(attr) == NODE_IDENT && self.dead.contains(&attr) {
                                        self.remove_with_prev_ws(attr);
                                    } else {
                                        self.scan(attr);
                                    }
                                }
                            }
                        }
                        _ => self.scan(child),
                    }
                }
            }
            Some(scope) if scope.kind == ScopeKind::LambdaArg => {
                let param = scope.param.unwrap();
                if let Some(ident) = tree.first_child_of_kind(param, NODE_IDENT) {
                    if self.dead.contains(&ident) {
                        let n = &tree.nodes[ident];
                        let replacement = format!("_{}", tree.node_text(ident));
                        self.edits.push(Edit { start: n.start, end: n.end, replacement });
                    }
                }
                if let Some(body) = scope.body {
                    self.scan(body);
                }
            }
            Some(scope) if scope.kind == ScopeKind::LambdaPattern => {
                let pattern = scope.param.unwrap();
                let children: Vec<usize> = tree.child_nodes(pattern).collect();
                for child in children {
                    match tree.kind(child) {
                        NODE_PAT_BIND => {
                            let dead = tree
                                .first_child_of_kind(child, NODE_IDENT)
                                .map_or(false, |id| self.dead.contains(&id));
                            if dead {
                                self.remove_pat_bind(child);
                            }
                        }
                        NODE_PAT_ENTRY => {
                            let dead = tree
                                .first_child_of_kind(child, NODE_IDENT)
                                .map_or(false, |id| self.dead.contains(&id));
                            if dead {
                                self.remove_pat_entry(child);
                            } else {
                                self.scan(child);
                            }
                        }
                        _ => self.scan(child),
                    }
                }
                if let Some(body) = scope.body {
                    self.scan(body);
                }
            }
            _ => {
                let children: Vec<usize> = tree.child_nodes(node).collect();
                for child in children {
                    self.scan(child);
                }
            }
        }
    }

    fn remove_pat_bind(&mut self, node: usize) {
        let tree = self.tree;
        let mut start = tree.nodes[node].start;
        let mut end = tree.nodes[node].end;
        let prev = tree.prev_sibling_or_token(Elem::Node(node));
        if self.is_ws(prev) {
            start = tree.elem_range(prev.unwrap()).0;
        }
        let next = tree.next_sibling_or_token(Elem::Node(node));
        if self.is_ws(next) {
            end = tree.elem_range(next.unwrap()).1;
        }
        self.remove(start, end);
    }

    fn remove_pat_entry(&mut self, node: usize) {
        let tree = self.tree;
        let mut start = tree.nodes[node].start;
        let mut end = tree.nodes[node].end;
        let prev = tree.prev_sibling_or_token(Elem::Node(node));
        if self.is_ws(prev) {
            start = tree.elem_range(prev.unwrap()).0;
        }
        let mut next = tree.next_sibling_or_token(Elem::Node(node));
        if self.is_ws(next) {
            next = tree.next_sibling_or_token(next.unwrap());
        }
        match next.map(|e| tree.elem_kind(e)) {
            Some(TOKEN_COMMA) => {
                end = tree.elem_range(next.unwrap()).1;
            }
            Some(TOKEN_R_BRACE) => {
                let mut p = prev;
                if self.is_ws(p) {
                    p = tree.prev_sibling_or_token(p.unwrap());
                }
                if let Some(p) = p {
                    if tree.elem_kind(p) == TOKEN_COMMA {
                        start = tree.elem_range(p).0;
                    }
                }
            }
            _ => {}
        }
        self.remove(start, end);
    }
}
