        Id::OutputFormat => "--output-format <OUTPUT_FORMAT>".to_string(),
        Id::Exclude => "--exclude <EXCLUDES>...".to_string(),
        Id::FilePaths => "[FILE_PATHS]...".to_string(),
        other => format!("--{}", def(other).long),
    }
