    /// Print to stdout and exit with code 0
    Print(String),
    /// Print to stderr and exit with code 2
    Error(String),
}

/// Jaro similarity, as used for suggestions
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);
    let mut a_flags = vec![false; a_len];
    let mut b_flags = vec![false; b_len];
    let mut matches = 0usize;
    for (i, ac) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = b_len.min(i + search_range + 1);
        for j in 0..max_bound {
            if min_bound <= j && *ac == b[j] && !b_flags[j] {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    let mut transpositions = 0usize;
    if matches != 0 {
        let mut b_iter = b_flags.iter().zip(b.iter());
        for (a_flag, ch1) in a_flags.iter().zip(a.iter()) {
            if *a_flag {
                loop {
                    if let Some((b_flag, ch2)) = b_iter.next() {
                        if !*b_flag {
                            continue;
                        }
                        if ch1 != ch2 {
                            transpositions += 1;
                        }
                        break;
                    } else {
                        break;
                    }
                }
            }
        }
    }
    transpositions /= 2;
    if matches == 0 {
        0.0
    } else {
        ((matches as f64 / a_len as f64)
            + (matches as f64 / b_len as f64)
            + ((matches - transpositions) as f64 / matches as f64))
            / 3.0
    }
}

fn did_you_mean<'a>(v: &str, candidates: impl Iterator<Item = &'a str>) -> Option<String> {
    let mut c: Vec<(f64, String)> = candidates
        .map(|pv| (jaro(v, pv), pv.to_owned()))
        .filter(|(confidence, _)| *confidence > 0.7)
        .collect();
    c.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    c.pop().map(|(_, s)| s)
}

struct State {
    bin: String,
    used: Vec<Id>,
    args: Args,
    seen: Vec<Id>,
}

impl State {
    fn generic_usage(&self) -> String {
        format!("Usage: {} [OPTIONS] [FILE_PATHS]...", self.bin)
    }

    fn smart_usage(&self, used: &[Id]) -> String {
        if used.is_empty() {
            return self.generic_usage();
        }
        let mut s = format!("Usage: {}", self.bin);
        let mut seen = Vec::new();
        for id in used {
            if *id == Id::FilePaths || seen.contains(id) {
                continue;
            }
            seen.push(*id);
            s.push(' ');
            s.push_str(&arg_display(*id));
        }
        if used.contains(&Id::FilePaths) {
            s.push_str(" <FILE_PATHS>...");
        } else {
            s.push_str(" [FILE_PATHS]...");
        }
        s
    }

    fn mark_used(&mut self, id: Id) {
        if !self.used.contains(&id) {
            self.used.push(id);
        }
    }

    fn error_footer() -> &'static str {
        "\nFor more information, try '--help'.\n"
    }

    fn err_multiple(&self, id: Id) -> CliResult {
        CliResult::Error(format!(
            "error: the argument '{}' cannot be used multiple times\n\n{}\n{}",
            arg_display(id),
            self.generic_usage(),
            Self::error_footer()
        ))
    }

    fn err_value_required(&self, id: Id) -> CliResult {
        let extra = if id == Id::OutputFormat {
            "\n  [possible values: human-readable, json]"
        } else {
            ""
        };
        CliResult::Error(format!(
            "error: a value is required for '{}' but none was supplied{}\n{}",
            arg_display(id),
            extra,
            Self::error_footer()
        ))
    }

    fn err_invalid_value(&self, value: &str) -> CliResult {
        let tip = match did_you_mean(value, POSSIBLE_VALUES.iter().copied()) {
            Some(s) => format!("\n  tip: a similar value exists: '{}'\n", s),
            None => String::new(),
        };
        CliResult::Error(format!(
            "error: invalid value '{}' for '{}'\n  [possible values: human-readable, json]\n{}{}",
            value,
            arg_display(Id::OutputFormat),
            tip,
            Self::error_footer()
        ))
    }

    /// Record an occurrence; returns an error on duplicates
    fn occur(&mut self, id: Id) -> Option<CliResult> {
        if self.seen.contains(&id) {
            return Some(self.err_multiple(id));
        }
        self.seen.push(id);
        self.mark_used(id);
        None
    }

    fn set_flag(&mut self, id: Id) -> Option<CliResult> {
        if let Some(e) = self.occur(id) {
            return Some(e);
        }
        match id {
            Id::NoLambdaArg => self.args.no_lambda_arg = true,
            Id::NoLambdaPatternNames => self.args.no_lambda_pattern_names = true,
            Id::NoUnderscore => self.args.no_underscore = true,
            Id::WarnUsedUnderscore => self.args.warn_used_underscore = true,
            Id::Quiet => self.args.quiet = true,
            Id::Edit => self.args.edit = true,
            Id::Hidden => self.args.hidden = true,
            Id::Fail => self.args.fail = true,
            Id::Help => return Some(CliResult::Print(help_text(&self.bin))),
            Id::Version => return Some(CliResult::Print("deadnix 1.3.1\n".to_string())),
            _ => {}
        }
        None
    }

    fn set_output_format(&mut self, value: &str) -> Option<CliResult> {
        if value.is_empty() {
            return Some(self.err_value_required(Id::OutputFormat));
        }
        match value {
            "human-readable" => self.args.output_format = OutputFormat::HumanReadable,
            "json" => self.args.output_format = OutputFormat::Json,
            other => return Some(self.err_invalid_value(other)),
        }
        None
    }
}

fn is_flag_like(s: &std::ffi::OsStr) -> bool {
    let b = s.as_encoded_bytes();
    b.len() > 1 && b[0] == b'-'
}

pub fn parse_args(argv: Vec<OsString>) -> CliResult {
    let bin = argv
        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| "deadnix".to_string());
    let mut st = State {
        bin,
        used: Vec::new(),
        args: Args {
            no_lambda_arg: false,
            no_lambda_pattern_names: false,
            no_underscore: false,
            warn_used_underscore: false,
            quiet: false,
            edit: false,
            hidden: false,
            fail: false,
            output_format: OutputFormat::HumanReadable,
            excludes: Vec::new(),
            file_paths: Vec::new(),
        },
        seen: Vec::new(),
    };

    let rest: Vec<OsString> = argv.into_iter().skip(1).collect();
    let mut i = 0;
    let mut trailing = false;
    // whether further plain values are appended to --exclude
    let mut collecting_excludes = false;

    while i < rest.len() {
        let arg = rest[i].clone();
        i += 1;
        if trailing {
            st.args.file_paths.push(arg);
            st.mark_used(Id::FilePaths);
            continue;
        }
        let lossy = arg.to_string_lossy().into_owned();
        if lossy == "--" {
            trailing = true;
            collecting_excludes = false;
            continue;
        }
        if lossy.starts_with("--") {
            collecting_excludes = false;
            let body = &lossy[2..];
            let (name, value) = match body.find('=') {
                Some(pos) => (&body[..pos], Some(&body[pos + 1..])),
                None => (body, None),
            };
            let found = ARGS.iter().find(|a| a.long == name);
            let a = match found {
                Some(a) => a,
                None => {
                    let suggestion = did_you_mean(name, ARGS.iter().map(|a| a.long));
                    return match suggestion {
                        Some(s) => {
                            let id = ARGS.iter().find(|a| a.long == s).unwrap().id;
                            let mut used = st.used.clone();
                            if !used.contains(&id) {
                                used.push(id);
                            }
                            CliResult::Error(format!(
                                "error: unexpected argument '--{}' found\n\n  tip: a similar argument exists: '--{}'\n\n{}\n{}",
                                name,
                                s,
                                st.smart_usage(&used),
                                State::error_footer()
                            ))
                        }
                        None => CliResult::Error(format!(
                            "error: unexpected argument '--{}' found\n\n  tip: to pass '--{}' as a value, use '-- --{}'\n\n{}\n{}",
                            name,
                            name,
                            name,
                            st.smart_usage(&st.used),
                            State::error_footer()
                        )),
                    };
                }
            };
            if !a.takes_value {
                if let Some(v) = value {
                    st.mark_used(a.id);
                    return CliResult::Error(format!(
                        "error: unexpected value '{}' for '--{}' found; no more were expected\n\n{}\n{}",
                        v,
                        a.long,
                        st.smart_usage(&st.used),
                        State::error_footer()
                    ));
                }
                if let Some(r) = st.set_flag(a.id) {
                    return r;
                }
                continue;
            }
            // option with value
            if let Some(e) = st.occur(a.id) {
                return e;
            }
            let v: OsString = match value {
                Some(v) => {
                    // value attached with '='
                    let start = 2 + name.len() + 1;
                    let raw = arg.as_encoded_bytes();
                    let v_raw = &raw[start.min(raw.len())..];
                    let _ = v;
                    // SAFETY: split at an ASCII '=' boundary of a valid OsStr
                    unsafe { OsString::from_encoded_bytes_unchecked(v_raw.to_vec()) }
                }
                None => {
                    if i < rest.len() && !is_flag_like(&rest[i]) && rest[i] != "--" {
                        i += 1;
                        rest[i - 1].clone()
                    } else {
                        return st.err_value_required(a.id);
                    }
                }
            };
            match a.id {
                Id::OutputFormat => {
                    if let Some(e) = st.set_output_format(&v.to_string_lossy()) {
                        return e;
                    }
                }
                Id::Exclude => {
                    st.args.excludes.push(v);
                    collecting_excludes = value.is_none();
                }
                _ => {}
            }
            continue;
        }
        if lossy.starts_with('-') && lossy.len() > 1 {
            collecting_excludes = false;
            let chars: Vec<char> = lossy[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                k += 1;
                let a = match ARGS.iter().find(|a| a.short == Some(c)) {
                    Some(a) => a,
                    None => {
                        return CliResult::Error(format!(
                            "error: unexpected argument '-{}' found\n\n  tip: to pass '-{}' as a value, use '-- -{}'\n\n{}\n{}",
                            c,
                            c,
                            c,
                            st.generic_usage(),
                            State::error_footer()
                        ));
                    }
                };
                if !a.takes_value {
                    if let Some(r) = st.set_flag(a.id) {
                        return r;
                    }
                    continue;
                }
                if let Some(e) = st.occur(a.id) {
                    return e;
                }
                let mut remainder: String = chars[k..].iter().collect();
                if remainder.starts_with('=') {
                    remainder.remove(0);
                }
                let value: String = if k < chars.len() {
                    remainder
                } else if i < rest.len() && !is_flag_like(&rest[i]) && rest[i] != "--" {
                    i += 1;
                    rest[i - 1].to_string_lossy().into_owned()
                } else {
                    return st.err_value_required(a.id);
                };
                if a.id == Id::OutputFormat {
                    if let Some(e) = st.set_output_format(&value) {
                        return e;
                    }
                }
                break;
            }
            continue;
        }
        // plain value
        if collecting_excludes {
            st.args.excludes.push(arg);
        } else {
            st.args.file_paths.push(arg);
            st.mark_used(Id::FilePaths);
        }
    }

    if st.args.file_paths.is_empty() {
        st.args.file_paths.push(OsString::from("."));
    }
    CliResult::Run(st.args)
}
EOF
echo ok

