// Recursive directory traversal (pre-order, directory read order).
use std::ffi::OsStr;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

#[derive(Debug)]
#[allow(dead_code)]
enum ErrorInner {
    Io { path: Option<PathBuf>, err: io::Error },
}

#[derive(Debug)]
#[allow(dead_code)]
pub struct Error {
    depth: usize,
    inner: ErrorInner,
}

pub struct DirEntry {
    pub path: PathBuf,
    pub is_dir: bool,
    pub is_file: bool,
}

impl DirEntry {
    pub fn file_name(&self) -> &OsStr {
        self.path.file_name().unwrap_or_else(|| self.path.as_os_str())
    }
}

pub struct WalkDir<F: FnMut(&DirEntry) -> bool> {
    root: Option<PathBuf>,
    stack: Vec<(usize, fs::ReadDir, PathBuf)>,
    pending_dir: Option<(usize, PathBuf)>,
    filter: F,
}

impl<F: FnMut(&DirEntry) -> bool> WalkDir<F> {
    pub fn new(root: &Path, filter: F) -> Self {
        WalkDir { root: Some(root.to_path_buf()), stack: Vec::new(), pending_dir: None, filter }
    }
}

impl<F: FnMut(&DirEntry) -> bool> Iterator for WalkDir<F> {
    type Item = Result<DirEntry, Error>;

    fn next(&mut self) -> Option<Self::Item> {
        if let Some(root) = self.root.take() {
            let md = match fs::metadata(&root) {
                Ok(md) => md,
                Err(err) => {
                    return Some(Err(Error { depth: 0, inner: ErrorInner::Io { path: Some(root), err } }))
                }
            };
            let entry = DirEntry { path: root, is_dir: md.is_dir(), is_file: md.is_file() };
            if (self.filter)(&entry) {
                if entry.is_dir {
                    self.pending_dir = Some((0, entry.path.clone()));
                }
                return Some(Ok(entry));
            }
            return None;
        }
        loop {
            if let Some((depth, dir)) = self.pending_dir.take() {
                match fs::read_dir(&dir) {
                    Ok(rd) => self.stack.push((depth, rd, dir)),
                    Err(err) => {
                        return Some(Err(Error { depth, inner: ErrorInner::Io { path: Some(dir), err } }))
                    }
                }
            }
            let (depth, rd, dir) = self.stack.last_mut()?;
            let depth = *depth;
            match rd.next() {
                None => {
                    self.stack.pop();
                    continue;
                }
                Some(Err(err)) => {
                    let path = dir.clone();
                    return Some(Err(Error { depth: depth + 1, inner: ErrorInner::Io { path: Some(path), err } }));
                }
                Some(Ok(de)) => {
                    let path = dir.join(de.file_name());
                    let ft = match de.file_type() {
                        Ok(ft) => ft,
                        Err(err) => {
                            return Some(Err(Error {
                                depth: depth + 1,
                                inner: ErrorInner::Io { path: Some(path), err },
                            }))
                        }
                    };
                    let entry = DirEntry { path, is_dir: ft.is_dir(), is_file: ft.is_file() };
                    if !(self.filter)(&entry) {
                        continue;
                    }
                    if entry.is_dir {
                        self.pending_dir = Some((depth + 1, entry.path.clone()));
                    }
                    return Some(Ok(entry));
                }
            }
        }
    }
}
