actions.command:
cd /workspace && cat > src/main.rs <<'EOF'
// deadnix: scan .nix files for dead code (unused variable bindings).
mod analysis;
mod cli;
mod edit;
mod parser;
mod report;
mod syntax;
mod tokenizer;
mod tree;
mod walk;
mod width;

use cli::{Args, CliResult, OutputFormat};
use std::collections::HashSet;
use std::ffi::OsStr;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

fn is_hidden(entry: &walk::DirEntry) -> bool {
    entry
        .file_name()
        .to_str()
        .map(|s| s.starts_with('.') && s != "." && s != "..")
        .unwrap_or(false)
}

fn is_nix_file(entry: &walk::DirEntry) -> bool {
    entry.is_file
        && entry
            .path
            .extension()
            .map_or(false, |ext: &OsStr| ext.eq_ignore_ascii_case("nix"))
}

struct Ctx {
    args: Args,
    settings: analysis::Settings,
    color: bool,
    found: bool,
}

impl Ctx {
    fn print_errors(&self, file: &str, prefix: &str, messages: &[String]) {
        match self.args.output_format {
            OutputFormat::HumanReadable => {
                for m in messages {
                    eprintln!("{} {}: {}", prefix, file, m);
                }
            }
            OutputFormat::Json => {
                let line = report::json_messages(file, messages);
                let mut out = std::io::stdout().lock();
                let _ = writeln!(out, "{}", line);
            }
        }
    }

    fn process_file(&mut self, path: &Path) {
        let file = path.display().to_string();
        let content = match fs::read_to_string(path) {
            Ok(content) => content,
            Err(e) => {
                self.print_errors(&file, "Error reading file", &[e.to_string()]);
                return;
            }
        };
        let (green, errors) = parser::parse(&content);
        if !errors.is_empty() {
            let messages: Vec<String> = errors.iter().map(|e| e.to_string()).collect();
            self.print_errors(&file, "Error parsing file", &messages);
            return;
        }
        let tree = tree::Tree::from_green(&content, green);
        let results = self.settings.find_dead_code(&tree);
        if results.is_empty() {
            return;
        }
        self.found = true;
        if !self.args.quiet {
            let text = match self.args.output_format {
                OutputFormat::HumanReadable => {
                    report::render(&file, &content, &tree, &results, self.color)
                }
                OutputFormat::Json => {
                    let mut s = report::json_results(&file, &content, &tree, &results);
                    s.push('\n');
                    s
                }
            };
            let mut out = std::io::stdout().lock();
            let _ = out.write_all(text.as_bytes());
            let _ = out.flush();
        }
        if self.args.edit {
            let new_content = edit::edit_dead_code(&content, &tree, &results);
            write_file(path, new_content);
        }
    }

    fn process_path(&mut self, path_os: &OsStr, excludes: &HashSet<PathBuf>) {
        let path = Path::new(path_os);
        match fs::metadata(path) {
            Err(e) => {
                let file = path.display().to_string();
                self.print_errors(&file, "Error stating file", &[e.to_string()]);
            }
            Ok(md) if md.is_dir() => {
                let hidden = self.args.hidden;
                let walker = walk::WalkDir::new(path, |entry: &walk::DirEntry| {
                    if !hidden && is_hidden(entry) {
                        return false;
                    }
                    if !excludes.is_empty() {
                        if let Ok(canonical) = fs::canonicalize(&entry.path) {
                            if excludes.contains(&canonical) {
                                return false;
                            }
                        }
                    }
                    true
                });
                for entry in walker.map(Result::unwrap) {
                    if is_nix_file(&entry) {
                        self.process_file(&entry.path);
                    }
                }
            }
            Ok(_) => self.process_file(path),
        }
    }
}

fn main() {
    let argv: Vec<std::ffi::OsString> = std::env::args_os().collect();
    let args = match cli::parse_args(argv) {
        CliResult::Run(args) => args,
        CliResult::Print(text) => {
            let mut out = std::io::stdout().lock();
            let _ = out.write_all(text.as_bytes());
            let _ = out.flush();
            std::process::exit(0);
        }
        CliResult::Error(text) => {
            let mut err = std::io::stderr().lock();
            let _ = err.write_all(text.as_bytes());
            let _ = err.flush();
            std::process::exit(2);
        }
    };

    let settings = analysis::Settings {
        no_lambda_arg: args.no_lambda_arg,
        no_lambda_pattern_names: args.no_lambda_pattern_names,
        no_underscore: args.no_underscore,
        warn_used_underscore: args.warn_used_underscore,
    };
    let color = std::env::var_os("NO_COLOR").is_none();
    let excludes: HashSet<PathBuf> =
        args.excludes.iter().filter_map(|p| fs::canonicalize(p).ok()).collect();
    let file_paths = args.file_paths.clone();
    let mut ctx = Ctx { args, settings, color, found: false };
    for path in &file_paths {
        ctx.process_path(path, &excludes);
    }
    if ctx.args.fail && ctx.found {
        std::process::exit(1);
    }
}

fn write_file(path: &Path, content: String) {
    fs::write(path, content).expect("fs::write");
}
