struct Editor<'t, 'a> {
    tree: &'t Tree<'a>,
    dead: HashSet<usize>,
    edits: Vec<Edit>,
}

impl<'t, 'a> Editor<'t, 'a> {
    fn is_ws(&self, e: Option<Elem>) -> bool {
        e.map_or(false, |e| self.tree.elem_kind(e) == TOKEN_WHITESPACE)
    }

    fn remove(&mut self, start: usize, end: usize) {
        self.edits.push(Edit { start, end, replacement: String::new() });
    }

    /// Remove a node together with the whitespace directly preceding it
    fn remove_with_prev_ws(&mut self, node: usize) {
        let tree = self.tree;
        let mut start = tree.nodes[node].start;
        let end = tree.nodes[node].end;
        let prev = tree.prev_sibling_or_token(Elem::Node(node));
        if self.is_ws(prev) {
            start = tree.elem_range(prev.unwrap()).0;
        }
        self.remove(start, end);
    }

    fn scan_dead(&mut self, node: usize) {
        let tree = self.tree;
        if self.dead.contains(&node) {
            let parent_kind = tree.nodes[node].parent.map(|p| tree.kind(p));
            match tree.kind(node) {
                NODE_PAT_BIND => self.remove_pat_bind(node),
                NODE_PAT_ENTRY => self.remove_pat_entry(node),
                NODE_IDENT if parent_kind == Some(NODE_IDENT_PARAM) => {
                    let n = &tree.nodes[node];
                    let replacement = format!("_{}", tree.node_text(node));
                    self.edits.push(Edit { start: n.start, end: n.end, replacement });
                }
                _ => self.remove_with_prev_ws(node),
            }
            return;
        }
        let children: Vec<usize> = tree.child_nodes(node).collect();
        for child in children {
            self.scan_dead(child);
        }
    }

    fn has_attrs(&self, inherit: usize) -> bool {
        self.tree.child_nodes(inherit).any(|c| is_attr_kind(self.tree.kind(c)))
    }

    fn let_in_body(&self, node: usize) -> Option<usize> {
        let tree = self.tree;
        tree.child_nodes(node).find(|&c| !matches!(tree.kind(c), NODE_ATTRPATH_VALUE | NODE_INHERIT))
    }

    fn scan_empty(&mut self, node: usize) {
        let tree = self.tree;
        match tree.kind(node) {
            NODE_LET_IN => {
                let empty = tree.child_nodes(node).all(|c| match tree.kind(c) {
                    NODE_ATTRPATH_VALUE => false,
                    NODE_INHERIT => !self.has_attrs(c),
                    _ => true,
                });
                if empty {
                    let body = self.let_in_body(node)
                        .expect("let_in.body");
                    self.remove(tree.nodes[node].start, tree.nodes[body].start);
                    self.scan_empty(body);
                    return;
                }
            }
            NODE_INHERIT => {
                if !self.has_attrs(node) {
                    self.remove_with_prev_ws(node);
                    return;
                }
            }
            _ => {}
        }
        let children: Vec<usize> = tree.child_nodes(node).collect();
        for child in children {
            self.scan_empty(child);
        }
    }

    fn remove_pat_bind(&mut self, node: usize) {
        let tree = self.tree;
        let mut start = tree.nodes[node].start;
        let mut end = tree.nodes[node].end;
        let prev = tree.prev_sibling_or_token(Elem::Node(node));
        if self.is_ws(prev) {
            start = tree.elem_range(prev.unwrap()).0;
        }
        let next = tree.next_sibling_or_token(Elem::Node(node));
        if self.is_ws(next) {
            end = tree.elem_range(next.unwrap()).1;
        }
        self.remove(start, end);
    }

    fn remove_pat_entry(&mut self, node: usize) {
        let tree = self.tree;
        let mut start = tree.nodes[node].start;
        let mut end = tree.nodes[node].end;
        let prev = tree.prev_sibling_or_token(Elem::Node(node));
        if self.is_ws(prev) {
            start = tree.elem_range(prev.unwrap()).0;
        }
        let mut next = tree.next_sibling_or_token(Elem::Node(node));
        if self.is_ws(next) {
            next = tree.next_sibling_or_token(next.unwrap());
        }
        match next.map(|e| tree.elem_kind(e)) {
            Some(TOKEN_COMMA) => {
                end = tree.elem_range(next.unwrap()).1;
            }
            Some(TOKEN_R_BRACE) => {
                let mut p = prev;
                if self.is_ws(p) {
                    p = tree.prev_sibling_or_token(p.unwrap());
                }
                if let Some(p) = p {
                    if tree.elem_kind(p) == TOKEN_COMMA {
                        start = tree.elem_range(p).0;
                    }
                }
            }
            _ => {}
        }
        self.remove(start, end);
    }
}
