rec {
  /* Map a function over an attrset.
     Example: mapAttrs' (n: v: nameValuePair n v) { a = 1; }
  */
  mapAttrs' = f: set:
    lib.listToAttrs (map (attr: f attr set.${attr}) (lib.attrNames set));

  fold = op: nul: list:
    let
      len = builtins.length list;
      fold' = n:
        if n == len
        then nul
        else op (builtins.elemAt list n) (fold' (n + 1));
    in fold' 0;

  compose = f: g: x: f (g x);

  id = x: x;

  const = x: y: x;

  flip = f: a: b: f b a;

  pipe = val: functions:
    let reverseApply = x: f: f x;
    in builtins.foldl' reverseApply val functions;

  optionalAttrs = cond: as: if cond then as else { };

  recursiveUpdateUntil = pred: lhs: rhs:
    let f = attrPath:
      lib.zipAttrsWith (n: values:
        let here = attrPath ++ [n]; in
        if lib.length values == 1
        || pred here (lib.elemAt values 1) (lib.head values) then
          lib.head values
        else
          f here values
      );
    in f [] [rhs lhs];
}
