import random, sys, cmp

NAMES = ['lib', 'stdenv', 'fetchurl', 'pkgs', 'self', 'super', 'version', 'pname', 'src', 'cfg', 'config', 'name', 'value',
         'x', 'y', 'f', 'g', 'args', 'inputs', 'system', 'overlay', 'final', 'prev', '_unused', '_x', 'deps', 'or', 'helper', 'list', 'attrs']

class G:
    def __init__(self, r):
        self.r = r
    def name(self):
        return self.r.choice(NAMES)
    def ind(self, d):
        return '  ' * d
    def comment(self, d):
        r = self.r.random()
        if r < 0.05: return self.ind(d) + '# deadnix: skip\n'
        if r < 0.1: return self.ind(d) + '# some comment\n'
        if r < 0.12: return self.ind(d) + '/* block */\n'
        return ''
    def expr(self, d, depth):
        r = self.r
        if depth <= 0:
            return r.choice([self.name(), self.name(), '"str"', '1', 'true', 'null', './file.nix', '"${%s}"' % self.name(), self.name() + '.' + self.name()])
        k = r.randrange(14)
        if k == 0: return self.let(d, depth)
        if k == 1: return self.lam(d, depth)
        if k == 2: return self.attrs(d, depth)
        if k == 3: return '[ ' + ' '.join(self.expr(d, depth-1) for _ in range(r.randrange(0, 4))) + ' ]'
        if k == 4: return self.name() + ' ' + self.expr(d, depth-1)
        if k == 5: return '(' + self.expr(d, depth-1) + ')'
        if k == 6: return 'with ' + self.name() + '; ' + self.expr(d, depth-1)
        if k == 7: return 'if ' + self.expr(d, depth-1) + ' then ' + self.expr(d, depth-1) + ' else ' + self.expr(d, depth-1)
        if k == 8: return "''\n" + self.ind(d+1) + 'echo ${' + self.expr(d, depth-1) + '} $out\n' + self.ind(d+1) + "''${HOME}\n" + self.ind(d) + "''"
        if k == 9: return self.expr(d, depth-1) + ' ' + r.choice(['++', '//', '+', '==', '&&', '||']) + ' ' + self.expr(d, depth-1)
        if k == 10: return self.name() + '.' + self.name() + ' or ' + self.expr(d, depth-1)
        if k == 11: return 'builtins.map (' + self.lam(d, depth-1) + ') ' + self.name()
        if k == 12: return 'import ./' + self.name() + '.nix { inherit ' + ' '.join(self.name() for _ in range(r.randrange(1,3))) + '; }'
        return self.name()
    def binding(self, d, depth, allow_inherit=True):
        r = self.r
        c = self.comment(d)
        k = r.randrange(6)
        if k == 0 and allow_inherit:
            return c + self.ind(d) + 'inherit ' + ' '.join(self.name() for _ in range(r.randrange(1, 4))) + ';\n'
        if k == 1 and allow_inherit:
            return c + self.ind(d) + 'inherit (' + self.name() + ') ' + ' '.join(self.name() for _ in range(r.randrange(1, 4))) + ';\n'
        if k == 2:
            return c + self.ind(d) + self.name() + '.' + self.name() + ' = ' + self.expr(d+1, depth-1) + ';\n'
        return c + self.ind(d) + self.name() + ' = ' + self.expr(d+1, depth-1) + ';' + r.choice(['', '', ' # trailing']) + '\n'
    def let(self, d, depth):
        r = self.r
        s = 'let\n'
        for _ in range(r.randrange(1, 6)):
            s += self.binding(d+1, depth)
        s += self.ind(d) + 'in\n' + self.ind(d) + self.expr(d, depth-1)
        return s
    def attrs(self, d, depth):
        r = self.r
        s = r.choice(['', 'rec ']) + '{\n'
        for _ in range(r.randrange(0, 5)):
            s += self.binding(d+1, depth)
        return s + self.ind(d) + '}'
    def pattern(self, d, depth):
        r = self.r
        names = [self.name() for _ in range(r.randrange(0, 6))]
        ents = []
        for n in names:
            if r.random() < 0.25:
                ents.append(n + ' ? ' + self.expr(d+1, max(0, depth-2)))
            else:
                ents.append(n)
        if r.random() < 0.4: ents.append('...')
        if r.random() < 0.5:
            p = '{ ' + ', '.join(ents) + ' }'
        else:
            p = '{\n' + ''.join(self.ind(d+1) + e + ',\n' for e in ents) + self.ind(d) + '}'
        k = r.random()
        if k < 0.2: p = self.name() + '@' + p
        elif k < 0.4: p = p + '@' + self.name()
        return p
    def lam(self, d, depth):
        r = self.r
        if r.random() < 0.5:
            return self.name() + ': ' + self.expr(d, depth-1)
        return self.pattern(d, depth) + ':\n' + self.ind(d) + self.expr(d, depth-1)
    def file(self):
        r = self.r
        return self.comment(0) + self.pattern(0, 3) + ':\n\n' + self.expr(0, r.randrange(2, 6)) + '\n'

if __name__ == '__main__':
    seed = int(sys.argv[1]); n = int(sys.argv[2])
    argsets = [a.split() for a in sys.argv[3:]] or [['-o', 'json', 'in.nix']]
    r = random.Random(seed)
    bad = 0
    for i in range(n):
        c = G(r).file()
        for a in argsets:
            if not cmp.compare(c, a):
                bad += 1
                if bad > 3: sys.exit(1)
    print("done", n, "bad", bad)
