        .first()
        .map(|a| {
            std::path::Path::new(a)
                .file_name()
                .map(|f| f.to_string_lossy().into_owned())
                .unwrap_or_else(|| a.to_string_lossy().into_owned())
        })
        .unwrap_or_else(|| "deadnix".to_string());
    let mut st = State {
        bin,
        matcher: Vec::new(),
        pending: None,
        args: Args {
            no_lambda_arg: false,
            no_lambda_pattern_names: false,
            no_underscore: false,
            warn_used_underscore: false,
            quiet: false,
            edit: false,
            hidden: false,
