                    let mut used = st.matcher.clone();
                    used.push(a.id);
                    let _ = st.resolve_pending();
                    return Err(CliResult::Error(format!(
                        "error: unexpected value '{}' for '--{}' found; no more were expected\n\n{}\n{}",
                        v,
                        a.long,
                        st.smart_usage(&used),
                        State::error_footer()
