            let lossy = arg.to_string_lossy().into_owned();
            let chars: Vec<char> = lossy[1..].chars().collect();
            let mut k = 0;
            while k < chars.len() {
                let c = chars[k];
                k += 1;
                let a = match ARGS.iter().find(|a| a.short == Some(c)) {
                    Some(a) => a,
                    None => return Err(st.unknown_short(c)),
                };
                if !a.takes_value {
                    st.resolve_pending()?;
                    st.react(a.id, Vec::new())?;
                    continue;
                }
