                } else {
                    st.pending = Some(Pending { id: a.id, values: Vec::new() });
                }
                break;
            }
            continue;
        }
        st.value(arg)?;
    }
    st.resolve_pending()?;
    let _ = is_flag_like;
    Ok(())
}
